const sourceLabels={unknown:'未確認',camera:'カメラ原本（自己申告）','adobe-existing':'既存Adobe Super Resolution処理済み',edited:'その他の加工済み'};
const adjustments=['brightness','contrast','warmth','sharpness'];let timer;
function message(t,error=false){$('status').textContent=t;$('status').classList.toggle('error',error);}
function model(){return S.current;}
function autoFor(m){return ArtworkBounds.detect(m.bitmap).map(c=>({...c,quad:c.quad.map(p=>({x:p.x*m.w/m.bitmap.width,y:p.y*m.h/m.bitmap.height}))}));}
function renderCandidates(){const m=model(),panel=$('boundaryCandidates');panel.replaceChildren();if(!m)return;const names={painting:'AIの作品候補',inner:'枠の内側候補',outer:'外周候補',boundary:'境界候補'};const note=document.createElement('p');note.className='hint';note.textContent=m.candidates?.length?'四隅が作品の端に合う候補を選んでください。額縁や絵柄を誤検出する場合があります。':'確かな候補がありません。低コントラスト・影・絵柄との競合では手動で四隅を指定してください。';panel.append(note);(m.candidates||[]).forEach((c,i)=>{const b=document.createElement('button');b.className='boundary-option'+(m.activeCandidate===i?' selected':'');b.dataset.candidateIndex=i;b.textContent=`${i+1} ${names[c.kind]}`;b.title=c.reasons.join(' / ');b.onclick=()=>{if(!S.working)previewCandidate(m,i);};panel.append(b);});$('confirmBoundary').disabled=!!S.pick||!m.candidatePending||!!S.hasDraft;$('cancelBoundary').disabled=!m.candidatePending;$('candidateState').textContent=m.candidatePending?'候補を表示中・保存前に確認が必要':'現在の四隅を表示中。必要なら手動で変更できます';}
